              }
            ]
          }
        ]
      },
      "effect": "suppress-rule",
      "targetRule": "d6b-uninsured-enhanced-review",
      "onUnknown": "ignore"
    },
    {
      "id": "suppress-d6c-on-rejection",
      "description": "Suppress D6c approval where a rejection clause governs.",
      "when": {
