            ]
          }
        ]
      },
      "effect": "suppress-rule",
      "targetRule": "d6c-low-moderate-risk-approval",
      "onUnknown": "ignore"
    },
    {
      "id": "suppress-o1-review-on-rejection",
      "description": "Suppress the O1 review rule where a rejection clause governs.",
      "when": {
        "op": "all",
        "conditions": [
          {
